def copy_fk_to_memberships(apps, schema_editor):
    AuditRun = apps.get_model("audits", "AuditRun")
    ExperimentRun = apps.get_model("audits", "ExperimentRun")
    rows = AuditRun.objects.exclude(experiment_id=None).values_list(
        "id", "experiment_id", "created_by_id", "created_at"
    )
    for run_id, experiment_id, user_id, created_at in rows.iterator():
        membership = ExperimentRun.objects.create(
            experiment_id=experiment_id, run_id=run_id, added_by_id=user_id
        )
        # auto_now_add stamps "now"; keep the original launch time instead.
        ExperimentRun.objects.filter(pk=membership.pk).update(added_at=created_at)


def copy_memberships_to_fk(apps, schema_editor):
    """Reverse: keep each run's earliest membership (the FK holds only one)."""
    AuditRun = apps.get_model("audits", "AuditRun")
    ExperimentRun = apps.get_model("audits", "ExperimentRun")
    seen = set()
    for run_id, experiment_id in ExperimentRun.objects.order_by(
        "added_at", "id"
    ).values_list("run_id", "experiment_id"):
        if run_id in seen:
            continue
        seen.add(run_id)
        AuditRun.objects.filter(pk=run_id).update(experiment_id=experiment_id)


